var Ud="́";   //  Знак ударения (чтобы был заметным)

 var k=0;    //  Счетчики в циклах
 var i=0;
 var j=0;
 var j2=0;
 var h=0;

 var T_pause=0;   //  продолжительность диалоговых пауз

 var mP;      //  Массив элементов-строк.
 var mPL;   //  Длина этого массива.
 var ptr;     //  Элемент строки.
 var s="";   //  Текст в строке.
 var s_="";   //  Текст в строке (для проверки изменений в строке после некоторых операций)
