 var count_P= 0;   //  Счетчик строк.

 var rS;      //  Результат детального поиска.
 var r_S;      //  Результат детального поиска.

 boxX=boxX/100;   //  Поправка для отступов окна от края экрана.
 boxY=boxY/100;











///////////////   ПРОВЕРКА РЕЖИМА

 if (fbwBody.style.display == "none") {     //  Если отображение текста книги отключено...
         window.external.SetStatusBarText("  •  Скрипт «"+ScriptName+"» v." + NumerusVersion + " можно запустить только в режиме «B» (Дизайн)");   //  то отправляем сообщение
         return;      //  и выходим из скрипта.
         }




 window.external.BeginUndoUnit(document, ScriptName + " v."+NumerusVersion);    //  Начало записи в систему отмен FBE.




///////////////   Полное удаление формата <FONT> в боди   (может остаться от какого-нибудь скрипта).
 mElem=fbwBody.getElementsByTagName("FONT");   //  Получаем все узлы <FONT> в "fbw_body".
 for (h=mElem.length-1; h>=0; h--)     //  Запускаем цикл для полученных элементов,
         mElem[h].removeNode(false);      //  Где удаляем формат <FONT>.




///////////////   БЛОКИРОВКА ФОРМАТА <code> от изменений

 var R_Code=true;         //  Индикатор обработки кода.
 var count_HeadCode=0;   //  Счетчик скрытых кодов.

 var mSpan = fbwBody.getElementsByTagName("SPAN");   //  Получение всех элементов <SPAN> в "fbw_body".
 var LSpan = mSpan.length;      //  Получение количества элементов.
 var mCode = [];              //  Массив с элементами <code>.
 var span;              //  Элемент <SPAN>.
 var el;     //  Элемент.

LBL_0:
 for (h=0;  h<LSpan;  h++) {   //  Последовательный просмотр элементов <SPAN>.
         span = mSpan[h];                  //  Даём имя очередному элементу <SPAN>.
         if (span.className != "code")   //  Если этот элемент не формат кода...
                 continue LBL_0;                         //  то переходим к следующему элементу.
         el = span;                       //  Создаем переменную, равную элементу <SPAN>.
         while (el.id != "fbw_body") {   //  Пока новый элемент не станет "fbw_body"...
                 el = el.parentNode;                                //  изменяем его на родительский элемент.
                 if (el.nodeName == "SPAN"  &&  el.className == "code")   //  Если он оказывается ещё одним элементом <code>.
                         continue LBL_0;        //  то переходим  к следующему элементу <SPAN> (формат код, вложенный внутрь другого кода, нам не нужен).
                 }
         mCode.push(span);   //  Записываем элемент в массив с найденными элементами <code>.
         }

         if (mCode.length !=0) {                   //  Если массив найденных элементов <code> не пустой.
                 FBWBodyPadding();   //  то запускаем функцию добавления внутренних полей в "fbw_body".

         wL = Math.round((scrW - 506) * boxX);    //  Отступ модального окна от левого края экрана.
         wT = Math.round((scrH - 127) * (1 - boxY));   //  Отступ модального окна от верхнего края экрана.   //   * 506 и 127 - размеры окна с рамкой.

         T_pause -= new Date().getTime();
         //  Запуск модального окна (Адрес, Импортируемые данные, Настройки: высота, ширина, отступ слева, отступ справа, help, изменение размера, строка состояния)
         var codeButton = window.showModalDialog(
                 "HTML/Текст-корректор - Блокировка формата code.html",
                 [mCode, textY, window, fbwBody, fbeH, fbeW, wT],
                 "dialogHeight: 100px; dialogWidth: 500px; dialogLeft: "+wL+"; dialogTop: "+wT+"; help: No; resizable: Yes; scroll: No; status: No");
         T_pause += new Date().getTime();   //  Отмечаем время, в течении которого отображалось окно.

         if (!codeButton)  codeButton = 6;       //  Если была нажата кнопка закрытия окна (крестик) - возвращаем код "6".

         window.scrollBy(0, -1);   window.scrollBy(0, 1);   //  Небольшой сдвиг текста для его правильного отображения.
         switch (codeButton) {    //  В зависимости от кода нажатой кнопки...
             case 3:                //  "Разрешить всё":
                 R_Code=true;    //  Включаем режим обработка кода.
                 break;
             case 4:                //  "Запретить всё":
                 R_Code=false;    //  Включаем режим запрета обработки кода.
                 count_HeadCode = mCode.length;   //  Получаем значение счетчика скрытых элементов <code>
                 break;
             case 6:                //  "Внеплановое закрытие окна":
                 R_Code=true;    //  Включаем режим обработка кода.
                 mElem=fbwBody.getElementsByTagName("FONT");   //  Получаем массив с одним не удаленным элементом <FONT>.
                 if (mElem[0])  mElem[0].removeNode(false);      //  Удаляем формат <FONT>.
                 }
         }










//////////////////////////////////    ОБРАБОТКА ТЕКСТА:  Переменные для функции "HandleP"    //////////////////////////////////

var sIB="<EM><STRONG>|<STRONG><EM>|<EM>|<STRONG>";
var fIB="</EM></STRONG>|</STRONG></EM>|</EM>|</STRONG>";
//  * Сдвоенные теги должны стоять в начале. Иначе, если в конце рег. выражения стоит ("+_IB+"), то формула находит в тексте только первый тег, а если за ним следует второй тег, то он игнорируется, и это может привести к ошибке.

var NC="<A [^>]+><SUP>\\{\\d{1,5}\\}</SUP></A>|<A class=note [^<]+</A>";   //  Любая стандартная сноска   на примечание или на комментарий.

var FalseSim="&&0&";    //  Спец.текст для нескольких небольших эпизодов.
var FalseCode="&&1&";   //  Спец.текст для формата <code>.
var FalseUrl="&&A&";   //  Спец.текст для адреса ссылки.

 var partisHandleP = 1;   //  Индикатор обработки (1 - основная обработка).
