 var code_=false;   //  Индикатор сохранения


/////  АДРЕСА

         //  Объединение ссылок   (формула для текста параграфов, т.е. как обычно)
 var re001 = new RegExp("(<A [^>]+>)([^<]*)</A>((?:\\s|"+nbspEntity+")*)\\1([^<]*</A>)","g");
 var re001_ = "$1$2$3$4";
 var count_001 = 0;

         //  Процентное кодирование адреса ссылки
 var count_002 = 0;


 var mainHtml = document.location.href;    //  Адрес файла с html-текстом книги.

         //  Ошибочное примечание с внешней ссылкой  (для A.href)
 var re003ex = new RegExp("^(?:"+mainHtml+")?#","g");
 var count_003 = 0;

         //  Удаление ссылок без адреса  (A.href="")
 var aNull = document.location.href.replace(/main\.html$/,"");
 var count_004 = 0;

         //  Удаление ссылок без текста или с малозаметным текстом  (для A.innerText)
 var re005 = new RegExp("^(?:\\s|"+nbspEntity+")*[\\.,;:]?(?:\\s|"+nbspEntity+")*$","g");
 var count_005 = 0;

         //  Временное скрытие и сохранение эл. адреса в массиве. (для параграфов, т.е. как обычно)
 var reHref = new RegExp("(href|src)=\"[^<>\"]*\"(?=[^<>]*>)","g");
 var mHref=[];             //  Массив для сохраненных фрагментов из одного абзаца.
 var href_ = false;    //  Индикатор наличия в строке скрытых адресов.
 var count_href = 0;



/////  ПОИСК

       //  Теги
 var Tag_ = false;   //  Любой тег.
 var Em_ = false;   //  Курсив.
 var St_ = false;   //  Жирность.
 var EmSt_ = false;   //  Курсив-жирность.
 var SubSup_ = false;   //  Верхний/нижний индексы.
 var reNoCom = new RegExp("<A class=note|><SUP>\\{\\d{1,5}\\}</SUP></A>","g");   //  Поиск примечаний и комментариев.
 var NoCom_ = false;     //  Примечания и комментарии.

       //  Разделы
 var poem_ = false;   //  Стихи

       //  Кавычки
