/////  ВАЛИДАЦИЯ ЗНАКОВ ПРЕПИНАНИЯ И Т.П.  :  операции  № 1хх

//  Удаление лишних знаков ударения   //  * Над коротким тире скрипт иногда ставит временный знак ударения для маркировки, и посторонний "маркер" будет мешать.
 var re101 = new RegExp("([\\-–—])"+Ud+"+","g");
 var re101_ = "$1";
 var count_101 = 0;

//  Замена символа угловых минут (<U+2032>) на апостроф (<U+2019>  или <U+0027>).
//  * Замена производится, если знак минут поставлен неверно - перед ним нет ни цифр, ни ещё одного знака минут.
 var re107 = new RegExp("(^|[^0-9′″])′","g");
 if (Apostrof != 0)  var re107_ = "$1’";
                           else  var re107_ = "$1'";
 var count_107 = 0;


//  Сдвоенный апостроф   ›››   прямые кавычки
 var re108 = new RegExp("(?:’’|'')","g");
 var re108_ = "\"";
 var count_108 = 0;


//  Замена кода н/р пробела на принятое обозначение в FBE
//  Устраняет небольшой глюк, который получается после вставки в FBE нескольких строк, после некоторых скриптов или действий в FBE
 var re115 = new RegExp("&nbsp;","g");
 var re115_ = nbspChar;
 var count_115 = 0;


//  Добавление пропущенного знака "&" в коде символа --  &amp;  и  &nbsp;
 var re116 = new RegExp("(^|[^A-Za-z;&])(?=amp;|nbsp;)","g");
 var re116_ = "$1&";
 var count_116 = 0;


       //  Внутренние теги

//  Выделение забытых точек/запятых
 var re118 = new RegExp("([\\.,]+)("+sIB+")([\\.,])|([\\?!\\.,])("+fIB+")([\\.,]+)","g");
 var re118_ = "$2$1$3$4$6$5";
 var count_118 = 0;

//  Нормализация пробелов на Окраине тегов
 var re119 = new RegExp("((?:\\s|"+nbspChar+")+)(</[^>]+>)|(<[A-Z][^>]*>)((?:\\s|"+nbspChar+")+)","g");
 var re119_ = "$2$1$4$3";
 var count_119 = 0;


       //  Ряд пробелов

//  Ряд пробелов   ›››   обычный пробел   (не в стихах)
 var re120 = new RegExp("(?:\\s|"+nbspChar+"){2,}","g");
 var re120_ = " ";
 var count_120 = 0;

//  Удаление начального пробела строки   (не в стихах)
 var re121 = new RegExp("^(?:\\s|"+nbspChar+")","g");
 var re121_ = "";
 var count_121 = 0;

//  Удаление конечных пробелов строки
 var re122 = new RegExp("(?:\\s|"+nbspChar+")+$","g");
 var re122_ = "";
 var count_122 = 0;


//  Исключение из обработки строк, целиком состоящих из 2-х и более символов:       .    \    /    *    _    -    –    —    ~    •    ·
//  Но допускается к обработке комбинация: тире/дефис (0-2 шт.)  + точки (2-4 шт.)
 var reSim = new RegExp("^(?:<[^/][^<>]*>)*(?:[\\.|\\\\/\\*_\\-–—~•·](?:\\s|"+nbspChar+")?){2,}(?:</[^<>]+>)*$","g");
 var reSim_ex = new RegExp("^(?:<[^/][^<>]*>)*[\\-–—~]{0,2}(?:(?:\\s|"+nbspChar+")?\\.){2,4}(?:</[^<>]+>)*$","g");
 var count_Sim = 0;

//  Удаление пробела перед % + 16-ричное число (в адресе).
 var re129 = new RegExp("((?:[A-Za-z]:[\\\\/]|www\\.|mailto:)[^<>\\s"+nbspChar+"]*)(?:\\s|"+nbspChar+")(?=%[0-9A-Fa-f]{2})");
 var re129_ = "$1";
 var count_129 = 0;


       //  Многоточие и т.п.

//  Три точки/запятые  ›››  многоточие
//  * Исключения:  |  , ...  |  ,,,  |
 var re130 = new RegExp("(\\s|"+nbspChar+")\\.[\\s"+nbspChar+"]?\\.[\\s"+nbspChar+"]?\\.|\\.[\\s"+nbspChar+"]?\\.[\\s"+nbspChar+"]?\\.(\\s|"+nbspChar+")|\\.[\\s"+nbspChar+"]\\.[\\s"+nbspChar+"]\\.|\\.[\\.,][\\.,]|[\\.,]\\.[\\.,]|[\\.,][\\.,]\\.","g");
 var re130_ = "$1…$2";
 var count_130 = 0;

//  Удаление точек/запятых после многоточия
 var re131= new RegExp("…[\\.,]+","g");
 var re131_ = "…";
 var count_131 = 0;

//  ? или ! + точки/запятые/многоточие ››› ?.. или !..
 var re132 = new RegExp("([!\\?])(\\.,|,\\.|,,|…)","g");
//  *    замена на:  "$1.."  ;   проверка значений:  $2 - точки/запятые/многоточие   =>    выбор счетчика
