 var re925main = new RegExp("(^|^[^_]?\\s|^[^_]?"+nbspEntity+"|[^_]{2}\\s|[^_]{2}"+nbspEntity+"|>)("+Z1+")(_"+Z1+sim+Z2+"_("+Z2+"(\\s|"+nbspEntity+")"+Z1+"_"+Z1+sim+Z2+"_)*)(?="+Z2+"(<|(\\s|"+nbspEntity+")([^_]{0,2}[^<>]*(<|$)|[^_]?$)|$))","g");
 var re925ex = new RegExp("^_"+Z1+sim+Z2+"_("+Z2+"(\\s|"+nbspEntity+")"+Z1+"_"+Z1+sim+Z2+"_)*$","g");   //  Исключение:  _символ_  ;  _символ_ _символ_


