///////////////   Статистика

 var count_change = 0;   //  Счетчик измененных строк.
 var maxCycle=0;                //  Максимум "циклов" обработки строки.
 var summaCycle=0;            //  Сумма "циклов" обработки.
 var midiCycle=0;                      //  Среднее значение "циклов" обработки.
 var mCycleL=mCycle.length;   //  Длина массива с количеством циклов.
 var PNoZero=mCycleL;      //  Количество ненулевых значений циклов.

 if (mCycle.length>0) {
         for (k=0; k<mCycleL; k++) {   //  Цикл для массива с количеством "циклов" обработки.
                 if (mChange[k])                           //  Если строка изменена...
                         count_change++;         //  то увеличиваем счетчик измененных строк.
                 if (mCycle[k]>maxCycle)   //  Если количество "циклов" обработки очередной строки больше максимума...
                         maxCycle=mCycle[k];   //  то изменяем максимум.
                 if (mCycle[k]!=0)                         //  Если цикл не нулевой...
                         summaCycle+=mCycle[k];   //  то суммируем количество "циклов" обработки.
                     else  PNoZero--;       //  В противном случае уменьшаем количество ненулевых значений циклов.
                 }
         if (PNoZero!=0)            //  Если количество ненулевых значений циклов больше ноля...
                 midiCycle = (Math.round(summaCycle/PNoZero*100)/100 + "").replace(".", ",");   //  то вычисляем среднее значение цикла.
             else  midiCycle=0;     //  В противном случае среднее значение приравниваем к нолю.
         }



